function auth(){try{return typeof Auth!=='undefined'?Auth:null;}catch(_){return null;}}
function user(){var a=auth();if(a&&a.user)return a.user;try{return JSON.parse(localStorage.getItem('sl_user')||'{}')||{};}catch(_){return{};}}
