L.dashboard=async function(){var b=document.querySelector('[data-focus-search]');if(b)b.onclick=function(){document.getElementById('search').focus();};try{var d=(await api('GET','/api/stratex-admin-centre/overview')).data||{};[['dashP',d.players],['dashC',d.coaches],['dashS',d.scouts],['dashA',(d.pendingRegistrations||0)+(d.pendingUsageRequests||0)+(d.openConcerns||0)]].forEach(function(x){var n=document.getElementById(x[0]);if(n)n.textContent=num(x[1]);});}catch(e){var root=document.getElementById('adminMain');if(root&&document.body.contains(root))root.insertAdjacentHTML('afterbegin',note('Live data unavailable',e.message||'The Admin API could not be reached.','red'));}};

/* Registrations */
function regStage(r){var s=String(r.status||'').toLowerCase(),v=String(r.verification_status||'').toLowerCase(),t=String(r.account_type||'').toLowerCase();if(s==='declined')return'declined';if(s==='approved'||v==='activated')return'account_created';if(t==='coach')return'admin_review';if(v==='verified_awaiting_payment')return'awaiting_payment';if(v==='documents_submitted')return'documents_ready';return'awaiting_documents';}
function regLabel(r){return{admin_review:'Admin review',awaiting_documents:'Awaiting documents',documents_ready:'Safeguarding review',awaiting_payment:'Awaiting payment',account_created:'Account created',declined:'Declined'}[regStage(r)]||'Review';}
R.registrations=function(){return hero('Growth','Registrations.','Coach and Scout applications move through a permanent, auditable workflow.',btn('Refresh','secondary','data-reg-refresh'),true)+'<section class="metrics">'+metric('All','—','Registration records','','regAll')+metric('Needs action','—','Admin or safeguarding review','gold','regAction')+metric('Documents','—','Waiting or submitted','blue','regDocs')+metric('Activated','—','Approved accounts','','regActive')+'</section><div id="regRows">'+loading()+'</div><div id="regDetail"></div>';};
L.registrations=function(){loadRegs();document.querySelector('[data-reg-refresh]').onclick=loadRegs;};
async function loadRegs(){try{var rows=(await api('GET','/api/registrations?limit=250&status=')).data||[];state.data.regs=rows;var vals={regAll:rows.length,regAction:rows.filter(function(r){return['admin_review','documents_ready','awaiting_payment'].includes(regStage(r));}).length,regDocs:rows.filter(function(r){return/ documents/.test(' '+regStage(r));}).length,regActive:rows.filter(function(r){return regStage(r)==='account_created';}).length};Object.keys(vals).forEach(function(id){var n=document.getElementById(id);if(n)n.textContent=num(vals[id]);});var rs=rows.map(function(r,i){return'<tr><td>'+record(name(r),(r.account_type||'')+' · '+(r.email||''),r)+'</td><td>'+esc(r.team_name||r.scout_club||'—')+'</td><td>'+esc(regLabel(r))+'</td><td>'+pill(r.status||'pending')+'</td><td>'+esc(date(r.created_at))+'</td><td>'+btn('Open','small','data-reg="'+i+'"')+'</td></tr>';}),ms=rows.map(function(r,i){return mrow(name(r),(r.account_type||'')+' · '+(r.team_name||r.scout_club||'No organisation'),regLabel(r)+' · '+date(r.created_at),r.status||'pending','data-reg="'+i+'"');});document.getElementById('regRows').innerHTML=table(['Applicant','Organisation','Stage','Decision','Submitted',''],rs,ms,'Registration records','Select an application to continue its workflow.');document.querySelectorAll('[data-reg]').forEach(function(n){n.onclick=function(){openReg(rows[+n.dataset.reg]);};});var id=qs().get('id');if(id){var r=rows.find(function(x){return String(x.id)===id;});if(r)openReg(r);}}catch(e){document.getElementById('regRows').innerHTML=empty(e.message);}}
function workflow(r){var st=regStage(r),sc=String(r.account_type||'').toLowerCase()==='scout',labels=sc?['Submitted','Documents','Safeguarding','Decision','Activation']:['Submitted','Review','Decision','Activation'],map={awaiting_documents:1,documents_ready:2,admin_review:1,awaiting_payment:3,account_created:labels.length,declined:2},a=map[st]||1;return'<section class="workflow" style="grid-template-columns:repeat('+labels.length+',1fr)">'+labels.map(function(l,i){var done=i<a,now=i===a&&st!=='account_created',dec=st==='declined'&&i>=a;return'<article class="'+(dec?'declined':now?'active':done?'done':'')+'"><span class="num">'+(done?'✓':i+1)+'</span><b>'+esc(l)+'</b><small>'+(now?'Action required':done?'Complete':'Not started')+'</small></article>';}).join('')+'</section>';}
function openReg(r){document.getElementById('regDetail').innerHTML=hero('Registration workflow',name(r)+'.','Complete the required access and safeguarding steps before activation.',r.email?'<a class="btn ghost" href="mailto:'+esc(r.email)+'">Email applicant</a>':'',false)+workflow(r)+'<div class="two-col">'+card('Applicant record',r.account_type||'Registration',details([['Email',r.email],['Phone',r.phone],['Organisation',r.team_name||r.scout_club],['Role',r.role_at_club||r.current_scouting_role||r.scout_league],['Status',r.status],['Verification',r.verification_status],['Plan',r.payment_plan||r.preferred_scout_plan],['Submitted',date(r.created_at)]]))+card('Workflow action',regLabel(r),regActions(r)+message('regMsg'))+'</div>';bindReg(r);document.getElementById('regDetail').scrollIntoView({behavior:'smooth'});}
function regActions(r){var st=regStage(r),o='<div class="hero-actions">';if(st==='admin_review')o+=btn('Approve Coach','','data-reg-action="approve"');if(st==='awaiting_documents')o+=btn('Resend verification','','data-reg-action="resend"');if(st==='documents_ready')o+=btn('Request information','secondary','data-reg-action="request"');if(st==='awaiting_payment')o+=btn('Payment received','','data-reg-action="paid"');if(!/account_created|declined/.test(st))o+=btn('Decline','danger','data-reg-action="decline"');return o+'</div>';}
function bindReg(r){document.querySelectorAll('[data-reg-action]').forEach(function(n){n.onclick=async function(){var a=n.dataset.regAction,ep='',body={};if(a==='approve'){if(!confirm('Approve this Coach registration and create the account?'))return;ep='/approve';}if(a==='resend')ep='/resend-verification';if(a==='paid'){if(!confirm('Confirm payment and create the Scout account?'))return;ep='/payment-received';body.subscriptionPlan=r.payment_plan||'Core';}if(a==='request'){var c=prompt('What information is required?');if(!c)return;ep='/request-information';body.message=c;}if(a==='decline'){var reason=prompt('Enter the decline reason.');if(!reason)return;ep='/decline';body={declineReason:'Other',customReason:reason};}try{await api('POST','/api/registrations/'+encodeURIComponent(r.id)+ep,body);msg('regMsg','Registration workflow updated.',true);await loadRegs();}catch(e){msg('regMsg',e.message,false);}};});}

