function openLead(r){document.getElementById('leadDetail').innerHTML=hero('Lead record',r.full_name||name(r)+'.','Keep the public submission and internal handling connected.',r.email?'<a class="btn ghost" href="mailto:'+esc(r.email)+'">Email</a>':'',false)+'<div class="two-col">'+card('Submission',r.lead_type||'Lead',details([['Email',r.email],['Phone',r.phone],['Organisation',r.organisation],['Role',r.role],['Reason',r.reason],['Message',r.message],['Source',r.source_page],['Received',date(r.created_at)]]))+card('Internal handling','Private admin notes','<form id="leadForm">'+field('Status','status','select',r.status||'new',['new','open','contacted','qualified','closed'])+field('Internal notes','notes','textarea','',null,'',true)+message('leadMsg')+'<button class="btn" type="submit">Save lead</button></form>')+'</div>';document.getElementById('leadForm').onsubmit=async function(e){e.preventDefault();var d=new FormData(e.currentTarget);try{await api('PATCH','/api/stratex-website/leads/'+encodeURIComponent(r.id),{status:d.get('status'),notes:d.get('notes')});msg('leadMsg','Lead updated.',true);}catch(x){msg('leadMsg',x.message,false);}};}
R.crm=function(){return hero('Growth','CRM.','A connected company view of leads, registrations, live accounts and candidates.',btn('Export CRM','secondary','data-export-crm'),true)+'<section class="metrics">'+metric('Contacts','—','Connected records','','crmN')+metric('ScoutLink','—','Product-linked contacts','blue','crmS')+metric('Stratex','—','Company leads and candidates','gold','crmX')+metric('Follow-up','—','Open or contacted','red','crmF')+'</section><div id="crmRows">'+loading()+'</div>';};
L.crm=async function(){document.querySelector('[data-export-crm]').onclick=async function(){try{var r=await fetch(API+'/api/stratex-website/crm/export',{headers:{Authorization:'Bearer '+token()},credentials:'include'});if(!r.ok)throw new Error('Export failed.');var b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='stratex-crm-export.xlsx';a.click();URL.revokeObjectURL(u);}catch(e){alert(e.message);}};try{var rows=(await api('GET','/api/stratex-website/crm')).data||[];[['crmN',rows.length],['crmS',rows.filter(function(r){return/scoutlink/i.test(String(r.product||r.source||''));}).length],['crmX',rows.filter(function(r){return!/scoutlink/i.test(String(r.product||r.source||''));}).length],['crmF',rows.filter(function(r){return/open|new|contacted|warm|follow/i.test(String(r.status||''));}).length]].forEach(function(x){document.getElementById(x[0]).textContent=num(x[1]);});var rs=rows.map(function(r){return'<tr><td>'+record(r.name||r.full_name||r.email,r.email||'',r)+'</td><td>'+esc(r.product||'Stratex')+'</td><td>'+esc(r.type||r.source||'Record')+'</td><td>'+esc(r.organisation||'—')+'</td><td>'+pill(r.status||'active')+'</td><td>'+esc(date(r.createdAt||r.created_at))+'</td></tr>';}),ms=rows.map(function(r){return mrow(r.name||r.full_name||r.email,(r.product||'Stratex')+' · '+(r.organisation||r.type||''),date(r.createdAt||r.created_at),r.status||'active','');});document.getElementById('crmRows').innerHTML=table(['Contact','Product','Type','Organisation','Status','Created'],rs,ms,'Connected CRM records','Player data is not included in the CRM.');}catch(e){document.getElementById('crmRows').innerHTML=empty(e.message);}};

