R.activity=function(){return hero('Growth','Website activity.','Privacy-conscious public-site traffic from Stratex activity events.',ext('Open public site',SITE,'secondary'),true)+'<section class="metrics">'+metric('Page views','—','Last 30 days','','av')+metric('Visitors','—','Hashed visitors','blue','auv')+metric('Sessions','—','Hashed sessions','gold','as')+metric('Top page','—','Highest traffic','purple','at')+'</section><div class="two-col"><div id="ac">'+loading()+'</div><div id="ap">'+loading()+'</div></div>';};
L.activity=async function(){try{var d=(await api('GET','/api/stratex-admin-centre/website-activity?days=30')).data||{};document.getElementById('av').textContent=num(d.pageViews);document.getElementById('auv').textContent=num(d.visitors);document.getElementById('as').textContent=num(d.sessions);document.getElementById('at').textContent=d.topPages&&d.topPages[0]?d.topPages[0].pagePath:'—';var a=(d.daily||[]).slice(-14),mx=Math.max.apply(null,a.map(function(x){return x.views;}).concat([1])),bars='<div class="chart-bars">'+a.map(function(x){return'<div class="chart-bar" style="height:'+Math.max(4,Math.round(x.views/mx*150))+'px"><b>'+num(x.views)+'</b><span>'+esc(x.date.slice(5))+'</span></div>';}).join('')+'</div>';document.getElementById('ac').innerHTML=card('Daily page views','Last 14 days',bars);document.getElementById('ap').innerHTML=card('Top pages','page_path breakdown','<div class="table-wrap mobile-scroll"><table class="data-table"><thead><tr><th>Page</th><th>Views</th></tr></thead><tbody>'+(d.topPages||[]).map(function(x){return'<tr><td>'+esc(x.pagePath)+'</td><td>'+num(x.views)+'</td></tr>';}).join('')+'</tbody></table></div>');}catch(e){document.getElementById('ac').innerHTML=empty(e.message);}};

