R.blog=function(){return hero('Content','Blog / Learning Centre.','Draft, edit, preview and publish articles to the actual public Learning Centre.',btn('New post','volt','data-new-post')+ext('Open Learning Centre',SITE+'/learning-centre','secondary'),false)+'<div id="blogRows">'+loading()+'</div>';};
L.blog=async function(){document.querySelector('[data-new-post]').onclick=function(){editPost(null);};try{var rows=(await api('GET','/api/stratex-website/blog')).data||[];state.data.blog=rows;var rs=rows.map(function(r,i){return'<tr><td>'+record(r.title,r.excerpt||'',r)+'</td><td>'+esc(r.category||'Learning')+'</td><td>'+pill(r.status||'draft')+'</td><td>'+num(r.view_count)+'</td><td>'+esc(date(r.updated_at||r.published_at))+'</td><td class="actions-cell">'+btn('Edit','small','data-post="'+i+'"')+(String(r.status).toLowerCase()==='published'?ext('View on site',SITE+'/learning-centre/'+encodeURIComponent(r.slug),'secondary small'):'')+'</td></tr>';}),ms=rows.map(function(r,i){return mrow(r.title,r.excerpt||'',date(r.updated_at||r.published_at),r.status||'draft','data-post="'+i+'"');});document.getElementById('blogRows').innerHTML=table(['Title / URL','Category','Status','Views','Updated','Actions'],rs,ms,'Blog & Learning Centre','Published articles link directly to the live public page.',btn('New post','small','data-new-post2'));document.querySelectorAll('[data-post]').forEach(function(n){n.onclick=function(){editPost(rows[+n.dataset.post]);};});document.querySelector('[data-new-post2]').onclick=function(){editPost(null);};}catch(e){document.getElementById('blogRows').innerHTML=empty(e.message);}};
async function editPost(r){r=r||{};if(r.id)try{r=(await api('GET','/api/stratex-website/blog/admin/'+encodeURIComponent(r.id))).data||r;}catch(_){}overlay(r.id?'Edit post':'New post','<form id="postForm"><div class="form-grid">'+field('Title','title','text',r.title||'',null,'',true,'required')+field('Slug','slug','text',r.slug||'',null,'Public URL slug.',true,'required')+field('Category','category','text',r.category||'Learning')+field('Status','status','select',r.status||'draft',[['draft','Draft'],['published','Published']])+field('Excerpt','excerpt','textarea',r.excerpt||'',null,'',true)+field('Body','body','textarea',r.body||'',null,'',true)+field('SEO title','seoTitle','text',r.seo_title||'',null,'',true)+field('Meta description','metaDescription','textarea',r.meta_description||'',null,'',true)+'<label class="field full"><span>Cover image</span><input class="input" name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"></label>'+field('Existing image URL','featuredImageUrl','text',r.featured_image_url||'',null,'',true)+field('Image alt text','imageAlt','text',r.image_alt||'',null,'',true)+field('Index when published','indexWhenPublished','select',r.index_when_published===false?'false':'true',[['true','Yes'],['false','No']])+'</div>'+message('postMsg')+'<div class="hero-actions"><button class="btn" type="submit">Save post</button>'+(r.slug?'<a class="btn secondary external-link" target="_blank" rel="noopener" href="'+SITE+'/learning-centre/'+encodeURIComponent(r.slug)+'">View on site</a>':'')+'</div></form>');document.getElementById('postForm').onsubmit=async function(e){e.preventDefault();var d=new FormData(e.currentTarget),image=d.get('featuredImageUrl');try{var file=d.get('imageFile');if(file&&file.name){var up=new FormData();up.append('image',file);var rr=await fetch(API+'/api/stratex-website/blog/image',{method:'POST',headers:{Authorization:'Bearer '+token()},body:up}),uu=await rr.json().catch(function(){return{};});if(!rr.ok)throw new Error(uu.error||'Image upload failed.');image=uu.url||image;}var b={title:d.get('title'),slug:d.get('slug'),category:d.get('category'),status:d.get('status'),excerpt:d.get('excerpt'),body:d.get('body'),seoTitle:d.get('seoTitle'),metaDescription:d.get('metaDescription'),featuredImageUrl:image,imageAlt:d.get('imageAlt'),indexWhenPublished:d.get('indexWhenPublished')==='true'};if(r.id)await api('PATCH','/api/stratex-website/blog/'+encodeURIComponent(r.id),b);else await api('POST','/api/stratex-website/blog',b);msg('postMsg',b.status==='published'?'Article published to the public Learning Centre.':'Draft saved.',true);setTimeout(function(){closeOverlay();L.blog();},450);}catch(x){msg('postMsg',x.message,false);}};}

