R.players=function(){return hero('ScoutLink Control','Players.','Search live player records, inspect calculated outputs, edit identity and the source 1–10 attribute assessment, or disqualify without deleting evidence.',btn('Refresh','secondary','data-refresh-players'),true)+'<section class="filters"><label class="field"><span>Search</span><input class="input" id="pSearch" placeholder="Name, team or Player ID"></label><label class="field"><span>Age group</span><select class="select" id="pAge"><option value="">All ages</option></select></label><label class="field"><span>Position</span><select class="select" id="pPos"><option value="">All positions</option></select></label><label class="field"><span>Status</span><select class="select" id="pStatus"><option value="">All</option><option value="true">Active</option><option value="false">Inactive</option></select></label>'+btn('Apply','','data-filter-players')+'</section><div id="pRows">'+loading()+'</div><div id="pDetail"></div>';};
async function scoring(){if(state.scoring)return state.scoring;state.scoring=await api('GET','/api/scoring/options');return state.scoring;}
L.players=async function(){await scoring();var a=document.getElementById('pAge'),p=document.getElementById('pPos');(state.scoring.ageGroups||[]).forEach(function(x){a.insertAdjacentHTML('beforeend','<option>'+esc(x)+'</option>');});(state.scoring.positions||[]).forEach(function(x){p.insertAdjacentHTML('beforeend','<option value="'+esc(x.code)+'">'+esc(x.code+' · '+x.label)+'</option>');});document.getElementById('pSearch').addEventListener('input',debounce(loadPlayers,250));document.querySelector('[data-filter-players]').onclick=loadPlayers;document.querySelector('[data-refresh-players]').onclick=loadPlayers;await loadPlayers();};
async function loadPlayers(){var q=new URLSearchParams(),s=(document.getElementById('pSearch')||{}).value||'',a=(document.getElementById('pAge')||{}).value||'',p=(document.getElementById('pPos')||{}).value||'',st=(document.getElementById('pStatus')||{}).value||'';if(s)q.set('q',s);if(a)q.set('ageGroup',a);if(p)q.set('position',p);if(st)q.set('active',st);q.set('limit','500');try{var rows=(await api('GET','/api/stratex-admin-centre/players?'+q)).data||[];state.data.players=rows;var rs=rows.map(function(r){return'<tr><td>'+record(name(r),(r.player_id||'')+' · '+(r.team_name||'No team'),r)+'</td><td>'+esc(r.age_group||'—')+'</td><td>'+esc(r.primary_position||r.specific_position||'—')+'</td><td><b>'+(r.overall_rating==null?'—':Number(r.overall_rating).toFixed(0))+'</b></td><td>'+pill(r.is_active===false?'Inactive':'Active')+'</td><td>'+btn('Open','small','data-player="'+r.id+'"')+'</td></tr>';}),ms=rows.map(function(r){return mrow(name(r),(r.primary_position||r.specific_position||'—')+' · '+(r.age_group||'—'),(r.team_name||'No team')+' · Overall '+(r.overall_rating==null?'—':Number(r.overall_rating).toFixed(0)),r.is_active===false?'Inactive':'Active','data-player="'+r.id+'"');});document.getElementById('pRows').innerHTML=table(['Player','Age','Position','Overall','Status',''],rs,ms,'ScoutLink players','Live records only. Demo players are excluded.');document.querySelectorAll('[data-player]').forEach(function(n){n.onclick=function(){openPlayer(n.dataset.player);};});var id=qs().get('id');if(id&&rows.some(function(r){return String(r.id)===id;}))openPlayer(id);}catch(e){document.getElementById('pRows').innerHTML=empty(e.message);}}
function ratingsView(x){var groups=Object.keys(x||{});if(!groups.length)return empty('No attribute assessment has been recorded.');return'<div class="attr-groups">'+groups.map(function(g){return'<section class="attr-group"><header><h4>'+esc(titleCase(g))+'</h4>'+pill(Object.keys(x[g]||{}).filter(function(k){return x[g][k]!=null;}).length+' rated','green')+'</header><div class="attr-grid">'+Object.keys(x[g]||{}).map(function(k){return'<div class="rating-field"><label>'+esc(attrLabel(k))+'</label><b>'+esc(x[g][k]==null?'Not observed':x[g][k]+'/10')+'</b></div>';}).join('')+'</div></section>';}).join('')+'</div>';}
async function openPlayer(id){var root=document.getElementById('pDetail');root.innerHTML=loading();try{var d=(await api('GET','/api/stratex-admin-centre/players/'+encodeURIComponent(id))).data||{},r=d.player||{},pot=r.prediction_analysis&&(r.prediction_analysis.potentialOverall||r.prediction_analysis.potentialRating||r.prediction_analysis.predictionScore),val=r.value_analysis&&(r.value_analysis.footballValueIndex||r.value_analysis.value),comp=d.compatibility&&d.compatibility[0];state.selected.player=d;root.innerHTML=hero('Player record',name(r)+'.','Admin view of identity, source assessment and calculated ScoutLink outputs.',btn('Edit player','volt','data-edit-player')+btn('Disqualify','danger','data-disq-player'),false)+'<section class="metrics">'+metric('Overall',r.overall_rating==null?'—':Number(r.overall_rating).toFixed(0),'Current position-specific ability')+metric('Potential',pot==null?'—':Number(pot).toFixed(0),'Bounded development outlook','blue')+metric('Value index',val==null?'—':Number(val).toFixed(0),'Football value profile','gold')+metric('Compatibility',comp?Number(comp.conservative_score||comp.compatibility_score||0).toFixed(0):'—','Latest stored team fit','purple')+'</section><div class="two-col">'+card('Profile','Identity and assignment',details([['Player ID',r.player_id],['Age group',r.age_group],['Position',r.primary_position||r.specific_position],['Alternatives',(r.alternative_positions||[]).join(', ')],['Team',r.team_name],['Coach',d.coach?name(d.coach):'—'],['Foot',r.foot],['Availability',r.availability]]))+card('Evidence','Profile inputs',details([['Match Facts',(d.matchFacts||[]).length],['Videos',(d.videos||[]).length],['Assessment version',r.attribute_assessment_version],['Assessed',date(r.attribute_assessed_at)],['Scoring version',r.scoring_version],['Status',r.is_active===false?'Inactive':'Active'],['Archived reason',r.archived_reason],['Updated',date(r.updated_at)]]))+'</div>'+card('Attribute assessment','The editable source assessment. Calculated outputs are never hand-edited.',ratingsView(r.attribute_ratings||{}));document.querySelector('[data-edit-player]').onclick=function(){editPlayer(d);};document.querySelector('[data-disq-player]').onclick=function(){disqualify(r);};root.scrollIntoView({behavior:'smooth'});}catch(e){root.innerHTML=empty(e.message);}}
function groupsFor(r){var pos=r.primary_position||r.specific_position||'',p=(state.scoring.positions||[]).find(function(x){return x.code===pos;}),g=p&&p.group;if(g==='Goalkeeper')return['goalkeeper'];return['general',{Defender:'defender',Midfielder:'midfielder',Attacker:'attacker'}[g]||String(g||'').toLowerCase()].filter(Boolean);}
function ratingsEditor(r){var cur=r.attribute_ratings||{},groups=groupsFor(r),gc=state.scoring.attributeGroups||{};return'<div class="attr-groups">'+groups.map(function(g){var keys=[];if(Array.isArray(gc[g]))keys=gc[g];else if(gc[g]&&Array.isArray(gc[g].attributes))keys=gc[g].attributes;if(!keys.length)keys=Object.keys(cur[g]||{});return'<section class="attr-group"><header><h4>'+esc(titleCase(g)+' attributes')+'</h4><span class="pill green">'+keys.length+' applicable</span></header><div class="attr-grid">'+keys.map(function(k){var v=cur[g]&&cur[g][k]!=null?String(cur[g][k]):'',o='<option value="">Not observed</option>';for(var n=1;n<=10;n++)o+='<option value="'+n+'"'+(v===String(n)?' selected':'')+'>'+n+'</option>';return'<div class="rating-field"><label>'+esc(attrLabel(k))+'<small>1–10 · blank means Not observed</small></label><select name="rating:'+esc(g)+':'+esc(k)+'">'+o+'</select></div>';}).join('')+'</div></section>';}).join('')+'</div>';}
async function editPlayer(d){
  await scoring();
  var r=d.player||{},teams=state.data.teams||[],coaches=state.data.coaches||[];
  if(!teams.length)try{teams=(await api('GET','/api/stratex-admin-centre/teams')).data||[];state.data.teams=teams;}catch(_){}
  if(!coaches.length)try{coaches=(await api('GET','/api/stratex-admin-centre/coaches')).data||[];state.data.coaches=coaches;}catch(_){}
  var currentPosition=r.primary_position||r.specific_position||'';
  var currentPositionDef=(state.scoring.positions||[]).find(function(x){return x.code===currentPosition;})||{};
  var currentGroup=currentPositionDef.group||r.position_group||'';
  var groupOptions=(state.scoring.positionGroups||[]).map(function(g){return[g.key,g.key==='Attacker'?'Forward':g.label||g.key];});
  var ages=state.scoring.ageGroups||[];
  var to=[['','No team']].concat(teams.filter(function(t){return t.is_active!==false;}).map(function(t){return[t.id,t.team_name];}));
  var co=[['','No assigned coach']].concat(coaches.filter(function(c){return c.is_active!==false;}).map(function(c){return[c.id,name(c)];}));
  var heightOptions=[['','Not set'],['very_tall','Very tall for age'],['tall','Tall for age'],['average','Average height for age'],['short','Below average height for age'],['very_short','Very short for age']];
  var buildOptions=[['','Not set'],['very_slight','Very slight build'],['slight','Slight build'],['lean','Slim / lean build'],['athletic','Athletic build'],['stocky','Stocky build'],['powerful','Powerful build'],['very_powerful','Very powerful build']];
  function positionOptions(group,selected){
    return (state.scoring.positions||[]).filter(function(x){return !group||x.group===group;}).map(function(x){return'<option value="'+esc(x.code)+'"'+(String(x.code)===String(selected)?' selected':'')+'>'+esc(x.label||x.code)+'</option>';}).join('');
  }
  overlay('Edit player - '+name(r),'<form id="playerForm"><div class="form-grid">'+
    field('First name','firstName','text',r.first_name)+
    field('Last name','lastName','text',r.last_name)+
    field('Age','age','number',r.age==null?'':r.age,null,'',false,'min="5" max="21" step="1"')+
    field('Age group','ageGroup','select',r.age_group,ages)+
    field('Position group','positionGroup','select',currentGroup,groupOptions)+
    '<label class="field"><span>Specific position</span><select class="select" name="primaryPosition" id="adminPlayerPosition">'+positionOptions(currentGroup,currentPosition)+'</select></label>'+
    field('Team','teamId','select',r.team_id||'',to)+
    field('Assigned coach','coachId','select',r.assigned_coach_id||'',co)+
    field('Height category','heightCategory','select',r.height_category||'',heightOptions)+
    field('Build category','buildCategory','select',r.build_category||'',buildOptions)+
    field('Preferred foot','foot','select',r.foot||'',[['','Not set'],['Right','Right'],['Left','Left'],['Both','Both']])+
    field('Availability','availability','text',r.availability||'')+
  '</div>'+note('Heads up','Changing team or coach re-parents future assessment responsibility. Existing evidence stays attached to this player record.','blue')+
  '<div style="margin-top:18px">'+note('Ratings are source data','Edit the 1–10 assessment below. Not observed remains blank. The canonical V4 engine recalculates Overall, position ratings, predictions and football value after save.','blue')+'<div id="adminPlayerRatings">'+ratingsEditor(r)+'</div></div>'+message('playerMsg')+
  '<div class="hero-actions" style="margin-top:18px"><button class="btn secondary" type="button" data-close-overlay>Cancel</button><button class="btn" type="submit">Save changes and recalculate</button></div></form>');
  var groupSelect=document.querySelector('[name="positionGroup"]'),positionSelect=document.getElementById('adminPlayerPosition');
  function refreshPlayerRatings(){var host=document.getElementById('adminPlayerRatings');if(host&&positionSelect)host.innerHTML=ratingsEditor(Object.assign({},r,{primary_position:positionSelect.value,specific_position:positionSelect.value}));}
  if(groupSelect&&positionSelect)groupSelect.addEventListener('change',function(){positionSelect.innerHTML=positionOptions(groupSelect.value,'');refreshPlayerRatings();});
  if(positionSelect)positionSelect.addEventListener('change',refreshPlayerRatings);
  document.getElementById('playerForm').onsubmit=async function(e){
    e.preventDefault();
    var fd=new FormData(e.currentTarget),ratings={};
    for(var pair of fd.entries()){
      if(pair[0].indexOf('rating:')!==0)continue;
      var bits=pair[0].split(':'),g=bits[1],k=bits.slice(2).join(':');
      if(!ratings[g])ratings[g]={};
      ratings[g][k]=pair[1]===''?null:Number(pair[1]);
    }
    var body={
      firstName:fd.get('firstName'),lastName:fd.get('lastName'),age:fd.get('age'),ageGroup:fd.get('ageGroup'),
      primaryPosition:fd.get('primaryPosition'),teamId:fd.get('teamId'),coachId:fd.get('coachId'),foot:fd.get('foot'),
      availability:fd.get('availability'),heightCategory:fd.get('heightCategory'),buildCategory:fd.get('buildCategory'),attributeRatings:ratings
    };
    try{
      var out=await api('PATCH','/api/stratex-admin-centre/players/'+encodeURIComponent(r.id),body);
      msg('playerMsg',out.warning||'Player saved and V4 outputs recalculated.',!out.warning);
      setTimeout(function(){closeOverlay();loadPlayers();openPlayer(r.id);},600);
    }catch(x){msg('playerMsg',x.message,false);}
  };
}
async function disqualify(r){var reason=prompt('Reason for disqualifying this player. The record and evidence will be preserved.');if(!reason||!confirm('Disqualify '+name(r)+'? This deactivates the player but does not delete evidence.'))return;try{await api('POST','/api/stratex-admin-centre/players/'+encodeURIComponent(r.id)+'/disqualify',{reason:reason});await loadPlayers();document.getElementById('pDetail').innerHTML='';}catch(e){alert(e.message);}}

