async function openCoach(id){var root=document.getElementById('cDetail');root.innerHTML=loading();try{var d=(await api('GET','/api/stratex-admin-centre/coaches/'+encodeURIComponent(id))).data||{},r=d.coach||{};root.innerHTML=hero('Coach record',name(r)+'.','Account access and current player responsibility.',btn('Manage access','volt','data-manage-coach'),false)+'<section class="metrics">'+metric('Players',(d.players||[]).length,'Assigned player records')+metric('Super User',r.is_super_user?'Yes':'No','Coach elevated access','blue')+metric('Team',r.team_name||'—','Current assignment','gold')+metric('Status',r.is_active===false?'Inactive':'Active','Account access','purple')+'</section>'+card('Coach details','Live account',details([['Email',r.email],['Phone',r.phone],['Role',r.role_at_club],['Team',r.team_name],['Registration',r.registration_complete?'Complete':'Incomplete'],['Last login',date(r.last_login,true)],['Created',date(r.created_at)],['Updated',date(r.updated_at)]]))+card('Assigned players','Current roster',(d.players||[]).length?'<div class="mrow-list">'+(d.players||[]).map(function(x){return mrow(name(x),(x.primary_position||'—')+' · '+(x.age_group||'—'),'Overall '+(x.overall_rating==null?'—':Number(x.overall_rating).toFixed(0)),x.is_active===false?'Inactive':'Active','data-jump-player="'+x.id+'"');}).join('')+'</div>':empty('No players assigned.'));document.querySelector('[data-manage-coach]').onclick=function(){manageCoach(r);};root.querySelectorAll('[data-jump-player]').forEach(function(n){n.onclick=function(){history.pushState({},'','/admin/scoutlink/players?id='+encodeURIComponent(n.dataset.jumpPlayer));go('players',false);};});}catch(e){root.innerHTML=empty(e.message);}}
async function manageCoach(r){var teams=state.data.teams||[];if(!teams.length)try{teams=(await api('GET','/api/stratex-admin-centre/teams')).data||[];state.data.teams=teams;}catch(_){}overlay('Manage Coach access','<form id="coachForm"><div class="form-grid">'+field('Account status','isActive','select',r.is_active===false?'false':'true',[['true','Active'],['false','Inactive']])+field('Super User','isSuperUser','select',r.is_super_user?'true':'false',[['false','Standard'],['true','Super User']])+field('Role at club','roleAtClub','text',r.role_at_club||'')+field('Team','teamId','select',r.team_id||'',[['','No team']].concat(teams.filter(function(t){return t.is_active!==false;}).map(function(t){return[t.id,t.team_name];})))+'</div>'+message('coachMsg')+'<button class="btn" type="submit">Save access</button></form>');document.getElementById('coachForm').onsubmit=async function(e){e.preventDefault();var d=new FormData(e.currentTarget);try{await api('PATCH','/api/stratex-admin-centre/coaches/'+encodeURIComponent(r.id),{isActive:d.get('isActive')==='true',isSuperUser:d.get('isSuperUser')==='true',roleAtClub:d.get('roleAtClub'),teamId:d.get('teamId')});msg('coachMsg','Coach access updated.',true);setTimeout(function(){closeOverlay();loadCoaches();openCoach(r.id);},450);}catch(x){msg('coachMsg',x.message,false);}};}

