R.teams=function(){return hero('ScoutLink Control','Teams.','Manage grassroots teams and preserve player and Coach evidence when a team leaves ScoutLink.',btn('Add team','volt','data-team-add'),true)+'<div id="tRows">'+loading()+'</div><div id="tDetail"></div>';};
