async function loadTeams(){try{var rows=(await api('GET','/api/stratex-admin-centre/teams')).data||[];state.data.teams=rows;var rs=rows.map(function(r){return'<tr><td>'+record(r.team_name,(r.city||r.county||'')+' · '+(r.league||r.league_name||''),{name:r.team_name})+'</td><td>'+num(r.playerCount)+'</td><td>'+num(r.coachCount)+'</td><td>'+pill(r.is_active===false?'Archived':'Active')+'</td><td>'+btn('Open','small','data-team="'+r.id+'"')+'</td></tr>';}),ms=rows.map(function(r){return mrow(r.team_name,(r.city||r.county||'')+' · '+(r.league||r.league_name||'No league'),r.playerCount+' players · '+r.coachCount+' coaches',r.is_active===false?'Archived':'Active','data-team="'+r.id+'"');});document.getElementById('tRows').innerHTML=table(['Team','Players','Coaches','Status',''],rs,ms,'Grassroots teams','Current and archived team records.');document.querySelectorAll('[data-team]').forEach(function(n){n.onclick=function(){openTeam(n.dataset.team);};});}catch(e){document.getElementById('tRows').innerHTML=empty(e.message);}}
function teamForm(){overlay('Add team','<form id="teamForm"><div class="form-grid">'+field('Team name','teamName','text','',null,'',true,'required')+field('County','county','text','')+field('City','city','text','')+field('Country','country','text','United Kingdom')+field('League','league','text','',null,'',true)+field('Contact email','contactEmail','email','')+field('FA Full-Time URL','leagueFulltimeUrl','url','',null,'',true)+field('Team website','teamWebsiteUrl','url','',null,'',true)+'</div>'+message('teamMsg')+'<button class="btn" type="submit">Create team</button></form>');document.getElementById('teamForm').onsubmit=async function(e){e.preventDefault();var d=new FormData(e.currentTarget),b={};d.forEach(function(v,k){b[k]=v;});try{await api('POST','/api/stratex-admin-centre/teams',b);msg('teamMsg','Team created.',true);setTimeout(function(){closeOverlay();loadTeams();},400);}catch(x){msg('teamMsg',x.message,false);}};}
async function openTeam(id){var root=document.getElementById('tDetail');root.innerHTML=loading();try{var d=(await api('GET','/api/stratex-admin-centre/teams/'+encodeURIComponent(id))).data||{},r=d.team||{};root.innerHTML=hero('Team record',r.team_name+'.','Roster links are live. Archiving unassigns people but does not delete records or evidence.',r.is_active===false?'':btn('Archive team','danger','data-team-archive'),false)+'<section class="metrics">'+metric('Players',(d.players||[]).length,'Linked player records')+metric('Coaches',(d.coaches||[]).length,'Linked Coach accounts','blue')+metric('League',r.league||r.league_name||'—','Competition','gold')+metric('Status',r.is_active===false?'Archived':'Active','Team lifecycle','purple')+'</section>'+card('Team details','Grassroots organisation',details([['County',r.county],['City',r.city],['Country',r.country],['Contact',r.contact_email],['League',r.league||r.league_name],['Full-Time URL',r.league_fulltime_url],['Website',r.team_website_url],['Created',date(r.created_at)]]))+'<div class="two-col">'+card('Coaches','Team staff',(d.coaches||[]).length?(d.coaches||[]).map(function(x){return'<div class="toggle-row"><div><b>'+esc(name(x))+'</b><span>'+esc(x.email||'')+'</span></div>'+pill(x.is_active===false?'Inactive':'Active')+'</div>';}).join(''):empty('No coaches linked.'))+card('Players','Team roster',(d.players||[]).length?(d.players||[]).slice(0,30).map(function(x){return'<div class="toggle-row"><div><b>'+esc(name(x))+'</b><span>'+esc((x.primary_position||'—')+' · '+(x.age_group||'—'))+'</span></div><b>'+(x.overall_rating==null?'—':Number(x.overall_rating).toFixed(0))+'</b></div>';}).join(''):empty('No players linked.'))+'</div>';var b=document.querySelector('[data-team-archive]');if(b)b.onclick=async function(){var reason=prompt('Why is this team being archived?');if(!reason||!confirm('Archive this team? Coaches and players are unassigned, not deleted.'))return;try{await api('POST','/api/stratex-admin-centre/teams/'+encodeURIComponent(r.id)+'/archive',{reason:reason});await loadTeams();root.innerHTML='';}catch(x){alert(x.message);}};}catch(e){root.innerHTML=empty(e.message);}}

/* Scouts and agencies */
R.scouts=function(){return hero('ScoutLink Control','Scouts & Agencies.','Manage reviewed Scout accounts, agency workspaces, plans and allowance requests.',btn('Add agency','volt','data-agency-add'),true)+'<nav class="tabs"><button class="active" data-stab="scouts">Scouts</button><button data-stab="agencies">Agencies</button><button data-stab="usage">Usage requests</button></nav><div id="sRows">'+loading()+'</div><div id="sDetail"></div>';};
L.scouts=async function(){document.querySelector('[data-agency-add]').onclick=agencyAdd;document.querySelectorAll('[data-stab]').forEach(function(n){n.onclick=function(){state.selected.stab=n.dataset.stab;document.querySelectorAll('[data-stab]').forEach(function(x){x.classList.toggle('active',x===n);});renderScoutTab();};});state.selected.stab=path()==='/admin/usage-requests'||qs().get('tab')==='usage'?'usage':'scouts';await loadScouts();};
async function loadScouts(){try{state.data.scoutBundle=(await api('GET','/api/stratex-admin-centre/scouts')).data||{};state.data.usage=(await api('GET','/api/usage-requests')).data||[];renderScoutTab();}catch(e){document.getElementById('sRows').innerHTML=empty(e.message);}}
function renderScoutTab(){var root=document.getElementById('sRows'),tab=state.selected.stab||'scouts';document.querySelectorAll('[data-stab]').forEach(function(n){n.classList.toggle('active',n.dataset.stab===tab);});if(tab==='scouts')return scoutList(root,state.data.scoutBundle.scouts||[]);if(tab==='agencies')return agencyList(root,state.data.scoutBundle.agencies||[]);return usageList(root,state.data.usage||[]);}
function scoutList(root,rows){var rs=rows.map(function(r){return'<tr><td>'+record(name(r),r.email||'',r)+'</td><td>'+esc(r.club_name||'—')+'</td><td>'+esc(r.subscription_plan||'Core')+'</td><td>'+pill(r.is_active===false?'Inactive':'Active')+'</td><td>'+btn('Open','small','data-scout="'+r.id+'"')+'</td></tr>';}),ms=rows.map(function(r){return mrow(name(r),(r.club_name||'No organisation')+' · '+(r.subscription_plan||'Core'),r.email||'',r.is_active===false?'Inactive':'Active','data-scout="'+r.id+'"');});root.innerHTML=table(['Scout','Organisation','Plan','Status',''],rs,ms,'Reviewed Scouts','Real Scout accounts only.');document.querySelectorAll('[data-scout]').forEach(function(n){n.onclick=function(){openScout(n.dataset.scout);};});}
function agencyList(root,rows){var scouts=state.data.scoutBundle.scouts||[],rs=rows.map(function(r){return'<tr><td>'+record(r.team_name||r.club_name,r.country||'',{name:r.team_name})+'</td><td>'+scouts.filter(function(s){return s.scout_team_id===r.id;}).length+'</td><td>'+esc(r.subscription_plan||'Core')+'</td><td>'+pill(r.status||'draft')+'</td><td>'+btn('Open','small','data-agency="'+r.id+'"')+'</td></tr>';}),ms=rows.map(function(r){return mrow(r.team_name||r.club_name,(r.subscription_plan||'Core')+' · '+(r.country||''),'Scout workspace',r.status||'draft','data-agency="'+r.id+'"');});root.innerHTML=table(['Agency / team','Seats','Plan','Status',''],rs,ms,'Scout agencies and teams','Subscription workspaces and seat assignments.');document.querySelectorAll('[data-agency]').forEach(function(n){n.onclick=function(){openAgency(n.dataset.agency);};});}
function usageList(root,rows){var rs=rows.map(function(r,i){return'<tr><td>'+esc(r.request_code||r.id)+'</td><td>'+esc(r.organisation_name||'—')+'</td><td>'+esc(r.allowance_type||'—')+'</td><td>'+num(r.quantity_requested)+'</td><td>'+pill(r.status||'pending')+'</td><td>'+btn('Open','small','data-usage="'+i+'"')+'</td></tr>';}),ms=rows.map(function(r,i){return mrow(r.request_code||'Usage request',(r.organisation_name||'')+' · '+(r.allowance_type||''),r.quantity_requested+' requested',r.status||'pending','data-usage="'+i+'"');});root.innerHTML=table(['Request','Organisation','Allowance','Quantity','Status',''],rs,ms,'Usage requests','Approve allowances or issue the payment workflow.');document.querySelectorAll('[data-usage]').forEach(function(n){n.onclick=function(){openUsage(rows[+n.dataset.usage]);};});}
