function scoutManage(r){var a=state.data.scoutBundle.agencies||[];overlay('Manage Scout','<form id="scoutForm"><div class="form-grid">'+field('Status','isActive','select',r.is_active===false?'false':'true',[['true','Active'],['false','Inactive']])+field('Plan','subscriptionPlan','select',r.subscription_plan||'Core',['Core','Plus','Elite','Enterprise'])+field('Agency','scoutTeamId','select',r.scout_team_id||'',[['','Individual Scout']].concat(a.map(function(x){return[x.id,x.team_name];})))+field('Exports remaining','exportsRemaining','number',r.exports_remaining||'')+field('Predictions remaining','predictionsRemaining','number',r.predictions_remaining||'')+field('Interests remaining','interestsRemaining','number',r.interests_remaining||'')+'</div>'+message('scoutMsg')+'<button class="btn" type="submit">Save Scout</button></form>');document.getElementById('scoutForm').onsubmit=async function(e){e.preventDefault();var d=new FormData(e.currentTarget);try{await api('PATCH','/api/stratex-admin-centre/scouts/'+encodeURIComponent(r.id),{isActive:d.get('isActive')==='true',subscriptionPlan:d.get('subscriptionPlan'),scoutTeamId:d.get('scoutTeamId'),exportsRemaining:d.get('exportsRemaining'),predictionsRemaining:d.get('predictionsRemaining'),interestsRemaining:d.get('interestsRemaining')});msg('scoutMsg','Scout updated.',true);setTimeout(function(){closeOverlay();loadScouts();openScout(r.id);},450);}catch(x){msg('scoutMsg',x.message,false);}};}
function agencyAdd(){overlay('Add Scout agency','<form id="agencyAdd"><div class="form-grid">'+field('Agency / scouting team','teamName','text','',null,'',true,'required')+field('Club name','clubName','text','')+field('Plan','subscriptionPlan','select','Core',['Core','Plus','Elite','Enterprise'])+field('Tier','tier','number','5')+field('Country','country','text','United Kingdom')+field('Formation','formation','text','')+field('Playing style','playingStyle','text','',null,'',true)+'</div>'+message('agencyAddMsg')+'<button class="btn" type="submit">Create draft agency</button></form>');document.getElementById('agencyAdd').onsubmit=async function(e){e.preventDefault();var d=new FormData(e.currentTarget),b={};d.forEach(function(v,k){b[k]=v;});try{await api('POST','/api/stratex-admin-centre/agencies',b);msg('agencyAddMsg','Draft agency created.',true);setTimeout(function(){closeOverlay();loadScouts();},450);}catch(x){msg('agencyAddMsg',x.message,false);}};}
