function admins(p){return Array.isArray(p)?p:(p.admins||p.data||p.users||[]);}
R.org=function(){return hero('Company','Org Directory.','Reporting lines and internal Stratex roles from live Admin user records.',null,true)+'<div id="orgRows">'+loading()+'</div>';};
